package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.IntervalSecondsVO;

class IntervalSecondsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of interval seconds of observed probe")
  void test_interval_seconds_value_holder_assign_plain_value() {
    Object holder = new Object();
    IntervalSecondsValueHolder<Object> value = new IntervalSecondsValueHolder<>(holder);
    Assertions.assertSame(holder, value.intervalSeconds(1), "Setters must return the holder");
    Assertions.assertTrue(value.getIntervalSecondsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getIntervalSeconds().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of interval seconds of observed probe")
  void test_interval_seconds_value_holder_assign_value_object() {
    Object holder = new Object();
    IntervalSecondsValueHolder<Object> value = new IntervalSecondsValueHolder<>(holder);
    IntervalSecondsVO vo = IntervalSecondsVO.from(1);
    Assertions.assertFalse(value.getIntervalSecondsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.intervalSeconds(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIntervalSecondsValue().orElseThrow());
    Assertions.assertSame(holder, value.intervalSeconds(Optional.empty()));
    Assertions.assertFalse(value.getIntervalSecondsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.intervalSeconds(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIntervalSecondsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of interval seconds of observed probe against the original")
  void test_interval_seconds_value_holder_read() {
    Object holder = new Object();
    IntervalSecondsValueHolder<Object> value = new IntervalSecondsValueHolder<>(holder);
    IntervalSecondsVO vo = IntervalSecondsVO.from(1);
    IntervalSecondsVO other = IntervalSecondsVO.from(1);
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getIntervalSecondsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIntervalSeconds(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readIntervalSeconds(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.intervalSeconds(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIntervalSeconds(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIntervalSeconds(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of interval seconds of observed probe")
  void test_interval_seconds_value_holder_unset() {
    Object holder = new Object();
    IntervalSecondsValueHolder<Object> value = new IntervalSecondsValueHolder<>(holder);
    IntervalSecondsVO vo = IntervalSecondsVO.from(1);
    value.intervalSeconds(vo);
    Assertions.assertSame(holder, value.unsetIntervalSecondsIfMatches("intervalSeconds_other"));
    Assertions.assertTrue(value.getIntervalSecondsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIntervalSecondsIfMatches("intervalSeconds"));
    Assertions.assertFalse(value.getIntervalSecondsValue().isPresent(),
        "The field name must clear the value");
    value.intervalSeconds(vo);
    Assertions.assertSame(holder, value.unsetIntervalSeconds());
    Assertions.assertFalse(value.getIntervalSecondsValue().isPresent(),
        "Unset must clear the value");
  }
}
